<dialog id="all-notes" class="slide-dialog notes-manager"><div class="dialog-head"><div><div class="eyebrow muted-eyebrow">PRIVATE TO THE PRESENTER</div><h2>Speaker notes</h2><p class="muted">These notes are only visible in the admin studio.</p></div><button type="button" class="close-button" onclick="this.closest('dialog').close()">×</button></div>@forelse ($slides as $slide)<details class="slide-note-item" id="note-entry-{{ $slide->id }}" @if($current?->id===$slide->id) open @endif><summary><span class="slide-icon {{ $slide->type }}">{{ $slide->type==='video'?'▶':($slide->type==='assessment'?'✳':'▤') }}</span><span><strong>{{ $slide->title }}</strong><small>{{ ucfirst(str_replace('_',' ',$slide->type)) }}{{ $current?->id===$slide->id ? ' · Selected' : '' }}</small></span></summary><form method="post" action="{{ route('slides.notes',$slide) }}">@csrf @method('PUT')<label class="notes-label">Presenter script or reminders<textarea name="notes" rows="6" maxlength="30000" placeholder="Add your talking points, cues, or reminders for this slide…">{{ $slide->notes }}</textarea></label><div class="notes-save-row"><small>Private speaker notes · not shown to students</small><button class="button primary compact-button">Save notes</button></div></form></details>@empty<p class="empty-questions">Add slides to start writing speaker notes.</p>@endforelse</dialog>
