function toggleOutlineForm(select){if(!select)return;const form=select.closest('form'),kind=select.value,parent=form.querySelector('#outline-parent'),special=form.querySelector('.special-deck-fields'),topicDeck=form.querySelector('.topic-deck-fields'),duration=special.querySelector('[name="duration_minutes"]'),specialType=special.querySelector('[name="special_type"]'),groupActivityHelp=special.querySelector('.group-activity-deck-help');special.hidden=kind!=='special_deck';topicDeck.hidden=kind!=='topic_deck';const updateSpecialFields=()=>{duration.closest('label').hidden=kind!=='special_deck'||specialType.value!=='break';duration.required=kind==='special_deck'&&specialType.value==='break';groupActivityHelp.hidden=kind!=='special_deck'||specialType.value!=='group_activity'};updateSpecialFields();for(const option of parent.options){const parentKind=option.value.split(':')[0];option.hidden=kind==='chapter'?parentKind!=='root':kind==='topic'?parentKind!=='chapter':kind==='topic_deck'?parentKind!=='topic':kind==='special_deck'?!['root','chapter','topic'].includes(parentKind):true}if(parent.selectedOptions[0]?.hidden){const firstVisible=[...parent.options].find(option=>!option.hidden);if(firstVisible)parent.value=firstVisible.value}parent.required=kind==='topic'||kind==='topic_deck';specialType.onchange=updateSpecialFields}
