function toggleQuestionFields(select){const form=select.closest('form'),field=form.querySelector('.question-options-field'),input=field.querySelector('[name="options_text"]');field.hidden=['short_answer','true_false'].includes(select.value);input.required=!field.hidden;const hint=field.querySelector('.question-hint');if(hint)hint.textContent=select.value==='matching'?'Enter at least two pairs, one per line, in “left | right” format.':'Enter at least two choices or items, one per line.';const answerHint=form.querySelector('.correct-answer-hint');if(answerHint)answerHint.textContent=({single_choice:'Enter the exact correct choice.',true_false:'Enter True or False.',multiple_choice:'Enter every correct choice, one per line.',short_answer:'Enter accepted answers, one per line.',ordering:'Enter every item in the correct order, one per line.',matching:'Enter every correct pair as “left | right”, one per line.'})[select.value]||'Enter the expected answer.'}
const confirmationDialog=document.getElementById('studio-confirmation');let confirmationResolve=null;function confirmInStudio(message,title='Please confirm',accept='Continue'){document.getElementById('confirmation-title').textContent=title;document.getElementById('confirmation-message').textContent=message;confirmationDialog.querySelector('[data-confirm-accept]').textContent=accept;confirmationDialog.showModal();return new Promise(resolve=>{confirmationResolve=resolve})}confirmationDialog.querySelector('[data-confirm-cancel]').addEventListener('click',()=>confirmationDialog.close('cancel'));confirmationDialog.querySelector('[data-confirm-accept]').addEventListener('click',()=>confirmationDialog.close('accept'));confirmationDialog.addEventListener('close',()=>{if(confirmationResolve){confirmationResolve(confirmationDialog.returnValue==='accept');confirmationResolve=null}});document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-confirm]');if(!form||form.dataset.confirmed==='true')return;event.preventDefault();if(await confirmInStudio(form.dataset.confirm,form.dataset.confirmTitle||'Please confirm',form.dataset.confirmAccept||'Continue')){form.dataset.confirmed='true';form.requestSubmit()}},{capture:true});
const renameDialog=document.getElementById('studio-rename');let renameResolve=null;function renameInStudio(kind,currentTitle){document.getElementById('rename-title').textContent='Rename '+kind;const input=document.getElementById('rename-value');input.value=currentTitle;renameDialog.showModal();input.focus();input.select();return new Promise(resolve=>{renameResolve=resolve})}renameDialog.querySelector('[data-rename-cancel]').addEventListener('click',()=>renameDialog.close('cancel'));renameDialog.querySelector('[data-rename-save]').addEventListener('click',()=>renameDialog.close('save'));renameDialog.addEventListener('close',()=>{if(renameResolve){renameResolve(renameDialog.returnValue==='save'?document.getElementById('rename-value').value.trim():null);renameResolve=null}});renameDialog.addEventListener('click',event=>{if(event.target===renameDialog)renameDialog.close('cancel')});document.getElementById('rename-value').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();renameDialog.close('save')}});
const activeEventId=document.body.dataset.eventId;if(activeEventId){document.querySelectorAll('form[method="post"]').forEach(form=>{if(!form.querySelector('[name="event_id"]')){const input=document.createElement('input');input.type='hidden';input.name='event_id';input.value=activeEventId;form.append(input)}})}if(@json(old('outline_kind') !== null))openOutlineModal();document.querySelectorAll('.type-select').forEach(s=>toggleFields(s));document.querySelectorAll('.layout-select').forEach(s=>toggleLayoutFields(s));document.querySelectorAll('.slide-editor-dialog form').forEach(form=>{form.addEventListener('input',()=>updateSlideMiniPreview(form));form.addEventListener('change',()=>updateSlideMiniPreview(form));updateSlideMiniPreview(form)});document.querySelectorAll('.question-type-select').forEach(s=>toggleQuestionFields(s));toggleOutlineForm(document.getElementById('outline-kind'));
const reopenQuestionSlide=@json(session('open_question_slide_id'));if(reopenQuestionSlide){const questionDialog=document.getElementById('questions-'+reopenQuestionSlide);if(questionDialog)questionDialog.showModal()}
const countdown=document.getElementById('admin-countdown'),sectionCountdown=document.getElementById('section-countdown');let timerEnded=false;function tickNode(node){if(!node)return;const remaining=Math.max(0,Math.floor((Number(node.dataset.end)-Date.now())/1000));node.textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(remaining===0&&!timerEnded){timerEnded=true;location.reload()}}function tickAdmin(){tickNode(countdown);tickNode(sectionCountdown)}tickAdmin();setInterval(tickAdmin,1000);
async function refreshStatus(){try{const r=await fetch(document.body.dataset.statusUrl,{headers:{Accept:'application/json'}});const d=await r.json();const n=document.getElementById('live-attendee-count');if(n)n.textContent=d.attendee_count}catch(e){}}setInterval(refreshStatus,3000);
const pauseCountdown=document.querySelector('.pause-countdown');if(pauseCountdown){function updatePauseCountdown(){const seconds=Math.max(0,Math.ceil((Number(pauseCountdown.dataset.end)-Date.now())/1000));pauseCountdown.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds===0)location.reload()}updatePauseCountdown();setInterval(updatePauseCountdown,1000)}
document.querySelectorAll('.sidebar-sort-item[draggable="true"]').forEach(item=>item.addEventListener('dragstart',event=>{if(event.target.closest('button,a,input,form')){event.preventDefault();return}event.stopPropagation();draggedOutlineItem=event.target.closest('.sidebar-sort-item');sourceOutlineContainer=item.parentElement.closest('.sidebar-sort-container');item.classList.add('is-dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',item.dataset.sortKind+':'+item.dataset.sortId)}));
let draggedOutlineItem=null,sourceOutlineContainer=null;
const outlineParentKinds={chapter:['root'],topic:['chapter'],topic_deck:['topic'],deck:['chapter','topic','root']};
document.querySelectorAll('.sidebar-sort-container').forEach(container=>{
 container.addEventListener('dragover',event=>{if(!draggedOutlineItem)return;const kind=draggedOutlineItem.dataset.sortKind,parentKind=container.dataset.sortParentKind,childKind=container.dataset.sortChildKind,allowedRootDeck=kind==='deck'&&draggedOutlineItem.dataset.sortSpecial==='true';if(!outlineParentKinds[kind]?.includes(parentKind)||(parentKind==='root'&&!allowedRootDeck)||(childKind!=='root_item'&&childKind!==kind)){event.stopPropagation();return}event.preventDefault();event.dataTransfer.dropEffect='move';container.classList.add('is-drop-target')});
 container.addEventListener('dragleave',event=>{if(!container.contains(event.relatedTarget))container.classList.remove('is-drop-target')});
 container.addEventListener('drop',async event=>{if(!draggedOutlineItem)return;const kind=draggedOutlineItem.dataset.sortKind,parentKind=container.dataset.sortParentKind,childKind=container.dataset.sortChildKind,allowedRootDeck=kind==='deck'&&draggedOutlineItem.dataset.sortSpecial==='true';if(!outlineParentKinds[kind]?.includes(parentKind)||(parentKind==='root'&&!allowedRootDeck)||(childKind!=='root_item'&&childKind!==kind)){event.stopPropagation();return}event.preventDefault();event.stopPropagation();container.classList.remove('is-drop-target');const target=event.target.closest('.sidebar-sort-item');if(target&&target!==draggedOutlineItem&&target.parentElement===container){const rect=target.getBoundingClientRect();container.insertBefore(draggedOutlineItem,event.clientY>rect.top+rect.height/2?target.nextSibling:target)}else if(draggedOutlineItem.parentElement!==container){container.appendChild(draggedOutlineItem)}const source=sourceOutlineContainer;const containers=[...new Set([source,container])].filter(Boolean);const payload={containers:containers.map(c=>({parent_kind:c.dataset.sortParentKind,parent_id:c.dataset.sortParentId||null,items:[...c.children].filter(x=>x.matches('.sidebar-sort-item')).map(x=>({kind:x.dataset.sortKind,id:Number(x.dataset.sortId)}))}))};draggedOutlineItem.classList.remove('is-dragging');draggedOutlineItem=null;sourceOutlineContainer=null;try{const token=document.querySelector('input[name="_token"]')?.value;const response=await fetch(document.body.dataset.outlineReorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify(payload)});if(!response.ok)throw new Error(await response.text());location.reload()}catch(error){await confirmInStudio('Could not save the outline order. The page will reload to restore the last saved version.','Outline not saved','Reload');location.reload()}})
});
