async function editOutlineItem(kind,id,currentTitle){const title=await renameInStudio(kind,currentTitle);if(!title||title===currentTitle)return;const response=await fetch('/admin/outline/'+kind+'/'+id,{method:'PATCH',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({title})});if(!response.ok){await confirmInStudio('Could not rename this '+kind+'. Try again.','Could not save','Close');return}location.reload()}
async function deleteOutlineItem(kind,id,title){if(!await confirmInStudio('Delete “'+title+'” and all of its slides, saved answers, and assessment results? If it is currently presented, students will move to the next available slide.','Delete '+kind+'?','Delete'))return;const response=await fetch('/admin/outline/'+kind+'/'+id,{method:'DELETE',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content}});if(!response.ok){await confirmInStudio('Could not delete this '+kind+'. Refresh the page and try again.','Could not delete','Close');return}location.reload()}
// Dismiss modal dialogs and the outline add popover when the user clicks outside.
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()}));

