@if($presenterMode)
<script>
(() => {
    const activeDeck = document.querySelector('.sidebar-deck-active');
    if (!activeDeck) return;

    const mobileOutline = activeDeck.closest('.presenter-mobile-outline-content');
    const isMobile = window.matchMedia('(max-width: 760px)').matches;
    if (isMobile && mobileOutline) {
        mobileOutline.classList.add('is-open');
        mobileOutline.closest('.presenter-mobile-outline')?.querySelector('.presenter-mobile-outline-toggle')?.setAttribute('aria-expanded', 'true');
    }

    const scrollContainer = isMobile ? mobileOutline : activeDeck.closest('.sidebar-outline-list');
    if (!scrollContainer) return;

    requestAnimationFrame(() => requestAnimationFrame(() => {
        const itemRect = activeDeck.getBoundingClientRect();
        const containerRect = scrollContainer.getBoundingClientRect();
        const targetTop = scrollContainer.scrollTop + itemRect.top - containerRect.top - (scrollContainer.clientHeight - itemRect.height) / 2;
        scrollContainer.scrollTo({ top: Math.max(0, targetTop), behavior: 'auto' });
    }));
})();
</script>
@endif
